'use strict';
const { shop, products } = require('../game/catalog.js');
const { step } = require('../game/engine.js');
const { openStore } = require('../game/save.js');
const { schemas } = require('../packages/cafe_tools.js');
function safeJson(o) {
  try { return JSON.stringify(o); } catch (_) { return 'null'; }
}
async function loadView() {
  const store = openStore(ToolPkg.getConfigDir(), Tools.Files);
  const previous = await store.read();
  const out = step(previous, 'snapshot', {}, schemas, Date.now());
  return out.view;
}
async function runAction(rawName, rawArgs) {
  const care = { cat_feed: "feed", cat_play: "play", cat_clean: "clean", cat_pet: "pet", cat_rest: "rest" };
  let name = rawName;
  const args = Object.assign({}, rawArgs || {});
  if (care[name]) {
    args.action = care[name];
    name = "care_for_cat";
  } else if (name === "business_assign_order") {
    name = "accept_order";
  }
  const store = openStore(ToolPkg.getConfigDir(), Tools.Files);
  const previous = await store.read();
  const out = step(previous, name, args, schemas, Date.now());
  if (out.changed) {
    await store.write({ state: out.state, revision: out.view.revision });
  }
  return { view: out.view, result: out.result };
}
